import{_ as e,o as i,c as t,a2 as r}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Performance Meeting 2018-10-04","description":"","frontmatter":{"title":"Ceph Performance Meeting 2018-10-04","date":"2018-10-04T00:00:00.000Z","updated":"2018-10-18T00:00:00.000Z","tags":["Ceph","分布式存储","性能","BlueStore","异步库"],"categories":["会议纪要"],"outline":"deep"},"headers":[],"relativePath":"posts/2018/Ceph_Performance_Meeting_2018-10-04.md","filePath":"posts/2018/Ceph_Performance_Meeting_2018-10-04.md","lastUpdated":1780460162000}'),o={name:"posts/2018/Ceph_Performance_Meeting_2018-10-04.md"};function s(n,l,p,a,u,g){return i(),t("div",null,[...l[0]||(l[0]=[r("<p>会议纪要</p><p><strong>会议时间</strong>： 2018年10月4日</p><p><strong>参会人员</strong>： Adam, Nick, Sage, Casey, Jason 以及其他未具名成员</p><p><strong>会议主题</strong>： Ceph 存储系统开发进展和讨论</p><p><strong>会议内容</strong>：</p><p><strong>1. 新 pull requests</strong></p><ul><li>Radek 提交的 pull request 改进了字符串处理，这是一个相对较小的改动，但效果显著。</li><li>Lebar 和 BD 共享的持久只读 RBD 缓存工作正在进行中，可能即将有新的代码提交。</li></ul><p><strong>2. Quick Blue Store 评估</strong></p><ul><li>Nick 对 Quick Blue Store 进行了实际评估，发现其性能表现良好，但存在一些问题。</li><li><strong>优点</strong>： <ul><li>压缩率约为 1.5 倍。</li><li>重写操作简单。</li><li>SSD 预测写入性能提升。</li><li>快照性能更好。</li></ul></li><li><strong>缺点</strong>： <ul><li>部分用例中性能较差。</li><li>延迟写入对新对象不适用，导致性能下降。</li><li>中等大小的写入操作（64KB 到 512KB）性能较差，因为超过延迟写入阈值后，所有操作都依赖于底层磁盘速度。</li><li>缺少合并，导致磁盘利用率过高。</li></ul></li><li><strong>建议</strong>： <ul><li>增加延迟写入阈值，以覆盖更大尺寸的写入操作。</li><li>考虑在 Blue Store 中使用缓存撕裂和写回技术。</li><li>使用 RAID 控制器和电池备份缓存，以改善性能。</li></ul></li></ul><p><strong>3. ASIO 和 C++ 异步库</strong></p><ul><li>Adam 介绍了 ASIO 异步网络和 I/O 层，它基于反应器模式，可以减少线程数量并提高效率。</li><li>ASIO 库的目的是： <ul><li>提供一个原生异步和集成到 Ceph 中的库。</li><li>避免不必要的内存分配。</li><li>提供更高级别的功能，例如命名空间和定位键。</li><li>统一 Rados 的各种线程执行上下文。</li></ul></li><li>Sage 和 Casey 讨论了 ASIO 库在 RGW 中的应用，包括协程和线程池。</li></ul><p><strong>4. 后续行动计划</strong></p><ul><li>Nick 将继续对 Quick Blue Store 进行测试和评估。</li><li>Adam 将继续开发 ASIO 库，并与其他开发者合作改进其性能。</li><li>Sage 和 Casey 将探索 ASIO 库在 RGW 中的应用。</li><li>Jason Dolman 将参与性能测试和评估。</li></ul><p><strong>会议总结</strong>：</p><p>本次会议讨论了 Ceph 存储系统开发中的多个重要议题，包括 Quick Blue Store 的性能评估和 ASIO 异步库的开发。与会者就这些问题进行了深入讨论，并制定了后续行动计划。</p>",15)])])}const S=e(o,[["render",s]]);export{c as __pageData,S as default};
